TypeScript example:
import { Client, RetryPolicy, idempotency } from '@redwood/sdk'
const client = new Client({ apiKey: process.env.REDWOOD_KEY, retryPolicy: RetryPolicy.default() })
const key = idempotency.generateDeterministic(['userId','payloadHash'], 'org-salt')
const resp = await client.generateText({ prompt: 'hi' }, { idempotencyKey: key })
